parameters.jsCode:
const resp = $input.item.json;
const body = $('Webhook 觸發出版社分析').item.json.body;
const { grade, subject, academicYear } = body;

let raw = (resp.choices?.[0]?.message?.content) || '';
raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();

let units = [];
try {
  const first = raw.indexOf('[');
  const last = raw.lastIndexOf(']');
  if (first !== -1 && last > first) {
    units = JSON.parse(raw.slice(first, last + 1));
  }
} catch(e) {
  console.error('Parse error:', e.message);
  return [];
}

const now = new Date().toISOString().slice(0, 10);
return units.map(u => ({ json: {
  recordName: `${grade}-${subject}-${u.unitName || '未知單元'}`,
  grade,
  subject,
  academicYear,
  publisher: u.publisher || '',
  unitName: u.unitName || '',
  weekNum: typeof u.weekNum === 'number' ? u.weekNum : 0,
  keyPoints: u.keyPoints || '',
  analysisDate: now
}}));

const items = $input.all();
const count = items.length;
const now = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });
const first = items[0]?.json || {};
const { grade, subject, academicYear } = first;
return [{ json: {
  count,
  grade, subject, academicYear,
  lineMsg: `【Mina 出版社分析完成 📖】
${academicYear} ${grade} ${subject}
識別 ${count} 個教學單元
已寫入 Notion 出題規範

可在 Notion 查看完整單元清單
時間：${now}`,
  emailSubject: `【Mina 題庫】${academicYear} ${grade} ${subject} 出版社分析完成，${count} 個單元`,
  emailBody: `Mina 出版社分析完成

學年度：${academicYear}
年級：${grade}
科目：${subject}
識別單元數：${count}

已寫入 Notion「出題規範」Database，供 AI 出題參考。

時間：${now}`
}}];
